   382	// Draws frame 0 (first column of the Idle row) of an 8x9 spritesheet as a preview.
   383	function drawThumb(cv: HTMLCanvasElement, url: string) {
   384	  const ctx = cv.getContext("2d");
   385	  if (!ctx) return;
   386	  ctx.imageSmoothingEnabled = false;
   387	  const img = new Image();
   388	  img.onload = () => {
   389	    const fw = img.naturalWidth / 8, fh = img.naturalHeight / 9;
   390	    if (!fw || !fh) return;
   391	    const sc = Math.min(cv.width / fw, cv.height / fh);
   392	    const dw = fw * sc, dh = fh * sc;
   393	    ctx.clearRect(0, 0, cv.width, cv.height);
   394	    ctx.drawImage(img, 0, 0, fw, fh, (cv.width - dw) / 2, (cv.height - dh) / 2, dw, dh);
   395	  };
   396	  img.src = url;
   397	}
